<?php declare(strict_types=1);$base=config('app.base_path');$isTrash=!empty($trash); ?><div class="page-header"><div><h1><?= $isTrash?'Deleted Fresh Food Businesses':'Fresh Food Businesses' ?></h1><p><?= $isTrash?'Restore deleted Fresh Food businesses.':'Create and manage unlimited Fresh Food and Grocery businesses.' ?></p></div><div class="page-actions"><?php if($isTrash): ?><a class="btn btn-secondary" href="<?= $base ?>/fresh-food/businesses">Active Businesses</a><?php else: ?><a class="btn btn-secondary" href="<?= $base ?>/fresh-food/businesses?view=trash">Trash</a><a class="btn btn-primary" href="<?= $base ?>/fresh-food/businesses/create">Add Fresh Food Business</a><?php endif; ?></div></div><div class="card"><table class="table"><thead><tr><th>Business</th><th>Location</th><th>Coordinates</th><th>Delivery</th><th>Products</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(empty($businesses)): ?><tr><td colspan="7"><div class="empty-state">No Fresh Food businesses found.</div></td></tr><?php else:foreach($businesses as $b): ?><tr><td><strong><?= htmlspecialchars((string)$b['business_name'],ENT_QUOTES,'UTF-8') ?></strong><br><small><?= htmlspecialchars((string)($b['phone']??''),ENT_QUOTES,'UTF-8') ?></small></td><td><?= htmlspecialchars((string)($b['city']??''),ENT_QUOTES,'UTF-8') ?><br><?= htmlspecialchars((string)($b['district']??''),ENT_QUOTES,'UTF-8') ?></td><td><?= $b['latitude']!==null?htmlspecialchars((string)$b['latitude'].' , '.(string)$b['longitude'],ENT_QUOTES,'UTF-8'):'Not set' ?></td><td>₹<?= number_format((float)$b['minimum_delivery_fee'],2) ?><br><small><?= number_format((float)$b['included_delivery_distance_km'],2) ?> km included</small></td><td><?= (int)$b['product_count'] ?></td><td><?= htmlspecialchars((string)$b['status'],ENT_QUOTES,'UTF-8') ?></td><td><?php if($isTrash): ?><form method="post" action="<?= $base ?>/fresh-food/businesses/<?= (int)$b['id'] ?>/restore"><button class="btn btn-secondary">Restore</button></form><?php else: ?><a class="link-button" href="<?= $base ?>/fresh-food/businesses/<?= (int)$b['id'] ?>">View</a> <a class="link-button" href="<?= $base ?>/fresh-food/businesses/<?= (int)$b['id'] ?>/edit">Edit</a><form method="post" action="<?= $base ?>/fresh-food/businesses/<?= (int)$b['id'] ?>/delete" style="display:inline"><button class="link-button" onclick="return confirm('Move this business to Trash?')">Delete</button></form><?php endif; ?></td></tr><?php endforeach;endif; ?></tbody></table></div>
